// ===== CONFIG (edit these) =====
const TZ = 'Asia/Karachi';  // clinic timezone
const OPEN = 9 * 60;               // 9:00 AM
const CLOSE = 17 * 60;             // 5:00 PM
const SLOT = 30;                   // appointment length in minutes
const STEP = 30;                   // gap between offered slots
const MAX_ALTERNATIVES = 3;
const CLOSED_WEEKDAYS = [0];       // 0 = Sunday

// ===== INPUT =====
const body = $('Webhook').first().json.body || {};
const args = body.args || body;
const reqDate = args.preferred_date;  // YYYY-MM-DD
const reqTime = args.preferred_time;  // HH:mm
const respond = (obj) => [{ json: obj }];

if (!/^\d{4}-\d{2}-\d{2}$/.test(reqDate || '') || !/^\d{1,2}:\d{2}$/.test(reqTime || '')) {
  return respond({ available: false, reason: 'invalid_input', alternatives: [],
    message: 'The date or time was not understood. Ask the caller to repeat it.' });
}

// ===== HELPERS =====
const pad = (n) => String(n).padStart(2, '0');
const hhmm = (m) => `${pad(Math.floor(m / 60))}:${pad(m % 60)}`;
const spoken = (m) => {
  const h24 = Math.floor(m / 60), mm = m % 60, h12 = h24 % 12 || 12;
  return `${h12}${mm ? ':' + pad(mm) : ''} ${h24 < 12 ? 'AM' : 'PM'}`;
};
const fmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
});
const localParts = (d) => {
  const p = Object.fromEntries(fmt.formatToParts(d).map((x) => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, mins: parseInt(p.hour) * 60 + parseInt(p.minute) };
};

const now = localParts(new Date());
const [rh, rm] = reqTime.split(':').map(Number);
const reqStart = rh * 60 + rm;
const weekday = new Date(`${reqDate}T12:00:00Z`).getUTCDay();

// ===== DAY-LEVEL RULES =====
if (reqDate < now.date) {
  return respond({ available: false, reason: 'past_date', alternatives: [],
    message: 'That date has already passed. Ask for a future date.' });
}
if (CLOSED_WEEKDAYS.includes(weekday)) {
  return respond({ available: false, reason: 'closed_day', alternatives: [],
    message: 'The clinic is closed on that day. Offer the next open day.' });
}
if (reqDate === now.date && now.mins >= CLOSE) {
  return respond({ available: false, reason: 'closed_for_today', alternatives: [],
    message: 'The clinic is closed for today. Offer tomorrow or another day.' });
}

// ===== BUSY INTERVALS FOR THAT DAY (clinic-local minutes) =====
const busy = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e || !e.start) continue;  // empty item from "Always Output Data"
  if (e.status === 'cancelled' || e.transparency === 'transparent') continue;

  if (e.start.date && !e.start.dateTime) {  // all-day event blocks the whole day
    if (e.start.date <= reqDate && reqDate < e.end.date) busy.push([0, 1440]);
    continue;
  }
  const sRaw = e.start.dateTime ?? (typeof e.start === 'string' ? e.start : null);
  const eRaw = e.end?.dateTime ?? (typeof e.end === 'string' ? e.end : null);
  if (!sRaw || !eRaw) continue;

  const s = localParts(new Date(sRaw));
  const en = localParts(new Date(eRaw));
  if (en.date < reqDate || s.date > reqDate) continue;
  busy.push([s.date < reqDate ? 0 : s.mins, en.date > reqDate ? 1440 : en.mins]);
}

const isFree = (s) => !busy.some(([bs, be]) => bs < s + SLOT && be > s);
const notPast = (s) => reqDate !== now.date || s > now.mins;

// ===== REQUESTED SLOT =====
const inHours = reqStart >= OPEN && reqStart + SLOT <= CLOSE;
const available = inHours && notPast(reqStart) && isFree(reqStart);

// ===== NEAREST FREE ALTERNATIVES =====
const grid = [];
for (let s = OPEN; s + SLOT <= CLOSE; s += STEP) {
  if (s !== reqStart && notPast(s) && isFree(s)) grid.push(s);
}
const alternatives = available ? [] : grid
  .sort((a, b) => Math.abs(a - reqStart) - Math.abs(b - reqStart))
  .slice(0, MAX_ALTERNATIVES)
  .sort((a, b) => a - b)
  .map((s) => ({ time: hhmm(s), spoken: spoken(s) }));

let reason = 'ok';
let message = 'The requested slot is free. Continue with the booking.';
if (!available) {
  reason = !inHours ? 'outside_hours' : !notPast(reqStart) ? 'time_passed' : 'slot_taken';
  message = alternatives.length
    ? 'The requested time is not available. Offer these alternative times on the same day.'
    : 'No free times are left on this day. Ask the caller for a different day.';
}

return respond({ available, reason, requested: { date: reqDate, time: reqTime }, alternatives, message });
